export class Pools {
  private readonly session = inject(Session);
  private readonly api = inject(PoolsApi);

  /** The people on the sheet (retired ones too). */
  readonly people = input.required<Person[]>();
  /** Each person's cut total in cents, by person id: their cuts across every pool they are a
   *  member of, added up (a pool that shows no cuts adds nothing). */
  readonly cutTotals = output<Map<number, number>>();

  protected readonly pools = signal<Pool[]>([]);
  protected readonly error = signal<string | null>(null);
  protected readonly noCuts = new Map<string, string>();
  /** Each pool's members' cuts, by pool name: a pool that is a member of none cuts the sheet's
   *  pot; a pool that is a member of another has no pot of its own but its cut in the pool above
   *  (none when that pool has no cuts). */
  protected readonly cuts = computed(() => {
    const pools = this.pools();
    const retiredIds = new Set(this.people().filter((p) => (p.retiredFrom ?? null) !== null).map((p) => p.id));
    const retired = (id: number) => retiredIds.has(id);
    const today = this.session.today();
    const heldIds = new Set(this.people().filter((p) => today !== null && heldOn(p.holds, today)).map((p) => p.id));
    const held = (id: number) => heldIds.has(id);
    const parentOf = new Map<string, string>();
    for (const p of pools) for (const m of p.members) if (m.pool !== null) parentOf.set(m.pool, p.name);
    const byName = new Map(pools.map((p) => [p.name, p]));
    const all = new Map<string, Map<string, string>>();
    const cutsFor = (pool: Pool, seen: Set<string>): Map<string, string> => {
      const known = all.get(pool.name);
      if (known) return known;
      const parent = parentOf.get(pool.name);
      let pot: string | null = this.session.pot();
      if (parent !== undefined) {
        const above = byName.get(parent);
        pot = above && !seen.has(parent)
          ? (cutsFor(above, new Set([...seen, pool.name])).get(`pool-${pool.name}`) ?? null)
          : null;
      }
      const cuts = cutsOf(pool, pot, retired, held, today);
      all.set(pool.name, cuts);
      return cuts;
    };
    for (const p of pools) cutsFor(p, new Set([p.name]));
    return all;
  });
  private saving = false;
  /** Guards against a slower, older read landing over a newer one. */
  private readSeq = 0;

  protected readonly form = new FormGroup({
    name: new FormControl('', { nonNullable: true }),
  });

  constructor() {
    this.form.valueChanges.subscribe(() => this.error.set(null));
    effect(() => {
      const totals = new Map<number, number>();
      const cuts = this.cuts();
      for (const p of this.pools()) {
        const poolCuts = cuts.get(p.name);
        for (const m of p.members) {
          const cut = poolCuts?.get(memberKey(m));
          if (m.personId !== null && cut !== undefined) totals.set(m.personId, (totals.get(m.personId) ?? 0) + cents(cut));
        }
      }
      untracked(() => this.cutTotals.emit(totals));
    });
    effect(() => {
      const id = this.session.sheetId();
      this.session.loads();
      untracked(() => {
        this.pools.set([]);
        this.error.set(null);
        this.form.reset({ name: '' }, { emitEvent: false });
        if (id) void this.read(id);
      });
    });
  }

  protected taken(pools: Pool[]): void {
    this.readSeq++;
    this.pools.set(pools);
  }

  protected async add(): Promise<void> {
    if (this.saving) return;
    this.error.set(null);
    const sheetId = this.session.sheetId();
    if (!sheetId) return;
    const name = this.form.getRawValue().name.trim();
    if (name === '') {
      this.error.set('Enter a name for the pool.');
      return;
    }
    if (this.pools().some((p) => p.name.toLowerCase() === name.toLowerCase())) {
      this.error.set('The sheet has a pool of that name already.');
      return;
    }
    this.saving = true;
    try {
      const pools = await this.api.add(sheetId, name);
      if (this.session.sheetId() === sheetId) this.taken(pools);
      this.form.reset({ name: '' }, { emitEvent: false });
    } catch (e) {
      this.error.set(poolError(e));
    } finally {
      this.saving = false;
    }
  }

  private async read(sheetId: string): Promise<void> {
    const seq = ++this.readSeq;
    try {
      const pools = await this.api.list(sheetId);
      if (seq === this.readSeq && this.session.sheetId() === sheetId) this.pools.set(pools);
    } catch {
      if (seq === this.readSeq) this.error.set('Something went wrong loading pools; try again.');
    }
  }
}
import { HttpClient, HttpErrorResponse } from '@angular/common/http';
import { Injectable, inject } from '@angular/core';
import { firstValueFrom } from 'rxjs';
import { Session, otherError } from '../../core/session';

/** A share percent: up to two decimals (more than 0.00 and at most 100.00 is checked apart). */
export const SHARE_PATTERN = /^\d{1,3}(\.\d{1,2})?$/;

/** A from- or to-date of a membership: yyyy-mm-dd. */
export const MEMBER_DATE_PATTERN = /^\d{4}-\d{2}-\d{2}$/;

/** A person, or another pool of the sheet, in a pool with their share percent (two decimals):
 *  exactly one of personId and pool is set. The membership may carry a from- and a to-date
 *  (yyyy-mm-dd, both inclusive, null when not given). */
export interface PoolMember {
  personId: number | null;
  pool: string | null;
  share: string;
  from: string | null;
  to: string | null;
}

/** Whether the membership's dates include the day (yyyy-mm-dd): a member outside them is left out
 *  of the pool entirely. With no day known, every member is in. */
export function memberOn(m: PoolMember, day: string | null): boolean {
  if (day === null) return true;
  return (m.from === null || m.from <= day) && (m.to === null || day <= m.to);
}

/** A member's key in its row's data-testid: the person's id, or pool-<name>. */
export function memberKey(m: PoolMember): string {
  return m.pool !== null ? `pool-${m.pool}` : String(m.personId);
}

/** A pool on the sheet: its name and its members, in the order they were added. */
export interface Pool {
  name: string;
  members: PoolMember[];
}

@Injectable({ providedIn: 'root' })
export class PoolsApi {
  private readonly http = inject(HttpClient);
  private readonly session = inject(Session);

  /** The sheet's pools, in the order they were added. */
  list(sheetId: string): Promise<Pool[]> {
    return firstValueFrom(this.http.get<Pool[]>(this.url(sheetId), { headers: this.headers() }));
  }

  /** Add a pool; resolves to the sheet's pools with it. */
  add(sheetId: string, name: string): Promise<Pool[]> {
    return firstValueFrom(this.http.post<Pool[]>(this.url(sheetId), { name }, { headers: this.headers() }));
  }

  /** Add a person, or another pool, to a pool with a share; resolves to the sheet's pools with them. */
  addMember(sheetId: string, pool: string, member: { personId: number } | { memberPool: string }, share: string,
    from: string, to: string): Promise<Pool[]> {
    return firstValueFrom(
      this.http.post<Pool[]>(`${this.url(sheetId)}/members`, { pool, ...member, share, from, to }, { headers: this.headers() }),
    );
  }

  private url(sheetId: string): string {
    return `/api/sheets/${encodeURIComponent(sheetId)}/pools`;
  }

  private headers(): Record<string, string> {
    return { 'X-User': this.session.user() ?? '' };
  }
}

export function poolError(e: unknown): string {
  if (e instanceof HttpErrorResponse && e.status === 400) return 'Enter a name for the pool.';
  if (e instanceof HttpErrorResponse && e.status === 409) return 'The sheet has a pool of that name already.';
  return otherError(e);
}

export function memberError(e: unknown): string {
  if (e instanceof HttpErrorResponse && e.status === 400) return 'Enter a share more than 0.00 and at most 100.00, with up to two decimals, and dates as yyyy-mm-dd.';
  if (e instanceof HttpErrorResponse && e.status === 409) return 'That person is in the pool already, or that pool is a member of a pool already.';
  if (e instanceof HttpErrorResponse && e.status === 422) return 'A pool cannot contain itself, a chain of pools is at most three deep, and a to-date is not before the from-date.';
  if (e instanceof HttpErrorResponse && e.status === 404) return 'That pool or person is no longer on the sheet; load the sheet again.';
  return otherError(e);
}
package net.officefloor.hq.app.pool;

import jakarta.validation.Valid;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Pattern;
import jakarta.validation.constraints.Size;
import java.math.BigDecimal;
import java.time.LocalDate;
import java.time.format.DateTimeParseException;
import java.util.List;
import java.util.Map;
import java.util.stream.Collectors;
import net.officefloor.hq.app.session.CurrentUser;
import org.springframework.http.HttpStatus;
import org.springframework.validation.annotation.Validated;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestHeader;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RestController;
import org.springframework.web.server.ResponseStatusException;

@RestController
@RequestMapping("/api/sheets/{sheetId}/pools")
@Validated
public class PoolController {

    /** A member as the screen shows it: the person's id, or the member pool's name, and the share
     *  with two decimals, and the membership's from- and to-date (yyyy-mm-dd, null when not given). */
    public record MemberView(Long personId, String pool, String share, String from, String to) {
        static MemberView of(PoolMember m, Map<Long, String> poolNames) {
            return new MemberView(m.getPersonId(),
                    m.getMemberPoolId() == null ? null : poolNames.get(m.getMemberPoolId()),
                    m.getShare().setScale(2).toPlainString(),
                    m.getFromDate() == null ? null : m.getFromDate().toString(),
                    m.getToDate() == null ? null : m.getToDate().toString());
        }
    }

    /** A pool as the screen shows it: its name and its members in the order they were added. */
    public record PoolView(String name, List<MemberView> members) {
        static PoolView of(PoolService.PoolWithMembers p, Map<Long, String> poolNames) {
            return new PoolView(p.pool().getName(),
                    p.members().stream().map(m -> MemberView.of(m, poolNames)).toList());
        }
    }

    /** A pool as the form submits it: a name (not blank). */
    public record PoolForm(@NotBlank @Size(max = 200) String name) {
    }

    /** A member as the pool's row submits it: the pool, a person or another pool of the sheet
     *  (exactly one), and a share percent with up to two decimals, more than 0.00 and at most
     *  100.00, and an optional from- and to-date (yyyy-mm-dd, blank for none). */
    public record MemberForm(
            @NotBlank @Size(max = 200) String pool,
            Long personId,
            @Size(max = 200) String memberPool,
            @NotNull @Pattern(regexp = "\\s*\\d{1,3}(\\.\\d{1,2})?\\s*") String share,
            @Pattern(regexp = "\\s*(\\d{4}-\\d{2}-\\d{2})?\\s*") String from,
            @Pattern(regexp = "\\s*(\\d{4}-\\d{2}-\\d{2})?\\s*") String to) {
    }

    private final PoolService service;

    public PoolController(PoolService service) {
        this.service = service;
    }

    @GetMapping
    public List<PoolView> list(
            @PathVariable @NotBlank @Size(max = 100) @Pattern(regexp = "\\S+") String sheetId,
            @RequestHeader(CurrentUser.HEADER) @NotBlank @Size(max = 100) String user) {
        List<PoolService.PoolWithMembers> all = service.list(sheetId);
        Map<Long, String> poolNames = all.stream()
                .collect(Collectors.toMap(p -> p.pool().getId(), p -> p.pool().getName()));
        return all.stream().map(p -> PoolView.of(p, poolNames)).toList();
    }

    /** Add a pool; resolves to the sheet's pools with it. */
    @PostMapping
    public List<PoolView> add(
            @PathVariable @NotBlank @Size(max = 100) @Pattern(regexp = "\\S+") String sheetId,
            @RequestHeader(CurrentUser.HEADER) @NotBlank @Size(max = 100) String user,
            @Valid @RequestBody PoolForm body) {
        service.add(sheetId, user.trim(), body.name().trim());
        return list(sheetId, user);
    }

    /** Add a member to a pool; resolves to the sheet's pools with it. */
    @PostMapping("/members")
    public List<PoolView> addMember(
            @PathVariable @NotBlank @Size(max = 100) @Pattern(regexp = "\\S+") String sheetId,
            @RequestHeader(CurrentUser.HEADER) @NotBlank @Size(max = 100) String user,
            @Valid @RequestBody MemberForm body) {
        boolean isPool = body.memberPool() != null && !body.memberPool().isBlank();
        if (isPool == (body.personId() != null)) {
            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "Choose a person or a pool");
        }
        BigDecimal share = share(body.share());
        LocalDate from = date(body.from());
        LocalDate to = date(body.to());
        if (from != null && to != null && to.isBefore(from)) {
            throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_CONTENT, "The to-date is before the from-date");
        }
        if (isPool) {
            service.addPoolMember(sheetId, user.trim(), body.pool().trim(), body.memberPool().trim(), share, from, to);
        } else {
            service.addMember(sheetId, user.trim(), body.pool().trim(), body.personId(), share, from, to);
        }
        return list(sheetId, user);
    }

    /** A date, null when blank; refused (400) when not a real date. */
    private static LocalDate date(String text) {
        if (text == null || text.isBlank()) return null;
        try {
            return LocalDate.parse(text.trim());
        } catch (DateTimeParseException e) {
            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "Not a date");
        }
    }

    /** The share, refused (400) unless more than 0.00 and at most 100.00. */
    private static BigDecimal share(String text) {
        BigDecimal share = new BigDecimal(text.trim()).setScale(2);
        if (share.signum() <= 0 || share.compareTo(new BigDecimal("100.00")) > 0) {
            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "A share is more than 0.00 and at most 100.00");
        }
        return share;
    }
}

