        }
      </form>
      <ul aria-label="Pools" data-testid="pools-list">
        @for (p of pools(); track p.name) {
          <li appPoolRow [pool]="p" [people]="people()" [pools]="pools()" [cuts]="cuts().get(p.name) ?? noCuts"
            (saved)="taken($event)"></li>
